import fs from 'node:fs';import assert from 'node:assert/strict';import crypto from 'node:crypto';
const root='reports/local/hero-matrix-20261023',ds=['easy','normal','hard','hell'];
const rows=ds.flatMap(d=>fs.existsSync(root+'/'+d+'.ndjson')?fs.readFileSync(root+'/'+d+'.ndjson','utf8').trim().split('\n').filter(Boolean).map(JSON.parse):[]);
const tally=rs=>rs.reduce((o,r)=>(o[r.outcome]=(o[r.outcome]??0)+1,o),{});
const median=xs=>{xs=xs.toSorted((a,b)=>a-b);return xs.length?(xs[Math.floor(xs.length/2)]+xs[Math.floor((xs.length-1)/2)])/2:null;};
const range=xs=>xs.length?[Math.min(...xs),Math.max(...xs)]:null;
const key=r=>[r.difficulty,r.stage,r.quality,r.race,r.mode,r.hero,r.members].join('/');assert.equal(new Set(rows.map(key)).size,rows.length);
const table=[];for(const difficulty of ds)for(const stage of [3,6,9])for(const quality of [0,3])for(const mode of ['boss','group','mixed']){const rs=rows.filter(r=>r.difficulty===difficulty&&r.stage===stage&&r.quality===quality&&r.mode===mode);table.push({difficulty,stage,quality,mode,baseline:tally(rs.filter(r=>!r.hero)),solo:tally(rs.filter(r=>r.hero&&r.members===0)),squad:tally(rs.filter(r=>r.hero&&r.members===4)),soloBossSeconds:mode==='boss'?range(rs.filter(r=>r.hero&&r.members===0&&r.outcome==='clear').map(r=>r.seconds)):null});}
const heroes=[...new Set(rows.filter(r=>r.hero).map(r=>r.hero))].map(hero=>{const rs=rows.filter(r=>r.hero===hero);return {hero,name:rs[0].name,solo:tally(rs.filter(r=>!r.members)),squad:tally(rs.filter(r=>r.members)),soloBossSeconds:range(rs.filter(r=>!r.members&&r.mode==='boss'&&r.outcome==='clear').map(r=>r.seconds)),notClear:rs.filter(r=>r.outcome!=='clear').map(({difficulty,stage,quality,mode,members,outcome,remaining,killed,expected,heroAlive})=>({difficulty,stage,quality,mode,members,outcome,remaining,killed,expected,heroAlive}))};});
const pairs=rows.filter(r=>r.hero&&r.members===4).map(r=>{const b=rows.find(b=>!b.hero&&b.difficulty===r.difficulty&&b.stage===r.stage&&b.quality===r.quality&&b.race===r.race&&b.mode===r.mode);assert.ok(b);assert.equal(b.expected,r.expected);return {difficulty:r.difficulty,stage:r.stage,quality:r.quality,race:r.race,mode:r.mode,hero:r.hero,baseline:b.outcome,heroOutcome:r.outcome,baselineDeaths:4-b.survivingInitial,withHeroDeaths:5-r.survivingInitial,secondsSaved:b.outcome==='clear'&&r.outcome==='clear'?b.seconds-r.seconds:null};});
const out={complete:rows.length===2808,total:rows.length,outcomes:tally(rows),baseline:tally(rows.filter(r=>!r.hero)),solo:tally(rows.filter(r=>r.hero&&!r.members)),squad:tally(rows.filter(r=>r.hero&&r.members)),table,heroes,pairs:{count:pairs.length,nonClearToClear:pairs.filter(p=>p.baseline!=='clear'&&p.heroOutcome==='clear').length,clearToNonClear:pairs.filter(p=>p.baseline==='clear'&&p.heroOutcome!=='clear').length,bothClear:pairs.filter(p=>p.baseline==='clear'&&p.heroOutcome==='clear').length,medianSecondsSavedBothClear:median(pairs.map(p=>p.secondsSaved).filter(x=>x!==null))}};
if(out.complete){const before=JSON.parse(fs.readFileSync(root+'/source-before.json','utf8'));for(const [file,hash] of Object.entries(before))assert.equal(crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex'),hash,file);out.sourceUnchanged=Object.keys(before).length;for(const d of ds){const summary=JSON.parse(fs.readFileSync(root+'/'+d+'-summary.json','utf8'));assert.equal(summary.rows,702);assert.equal(summary.sourceUnchanged,true);}assert.equal(rows.filter(r=>!r.hero).length,216);assert.equal(rows.filter(r=>r.hero&&!r.members).length,1296);assert.equal(rows.filter(r=>r.hero&&r.members).length,1296);assert.ok(!rows.some(r=>r.outcome==='blocked'));}
Object.assign(out,{byMode:['boss','group','mixed'].map(mode=>({mode,baseline:tally(rows.filter(r=>!r.hero&&r.mode===mode)),solo:tally(rows.filter(r=>r.hero&&!r.members&&r.mode===mode)),squad:tally(rows.filter(r=>r.hero&&r.members&&r.mode===mode))})),bossTimes:[3,6,9].map(stage=>{const rs=rows.filter(r=>r.hero&&!r.members&&r.mode==='boss'&&r.stage===stage&&r.outcome==='clear');return {stage,count:rs.length,range:range(rs.map(r=>r.seconds)),median:median(rs.map(r=>r.seconds))};})});
Object.assign(out,{bossByQuality:[3,6,9].flatMap(stage=>[0,3].map(quality=>{const rs=rows.filter(r=>r.hero&&!r.members&&r.mode==='boss'&&r.stage===stage&&r.quality===quality);return {stage,quality,count:rs.length,outcomes:tally(rs),range:range(rs.filter(r=>r.outcome==='clear').map(r=>r.seconds)),median:median(rs.filter(r=>r.outcome==='clear').map(r=>r.seconds))};}))});
fs.writeFileSync(root+'/analysis.json',JSON.stringify(out,null,2));console.log(JSON.stringify({complete:out.complete,total:out.total,baseline:out.baseline,solo:out.solo,squad:out.squad,pairs:out.pairs}));
if(out.complete){
 for(const d of ds)for(const s of [3,6,9])for(const q of [0,3])for(const mode of ['boss','group','mixed']){const part=rows.filter(r=>r.difficulty===d&&r.stage===s&&r.quality===q&&r.mode===mode);assert.equal(part.length,39);assert.equal(new Set(part.map(r=>r.expected)).size,1);}
 for(const r of rows){assert.equal(r.initial.filter(u=>u.hero).length,r.hero?1:0);assert.equal(r.initial.filter(u=>!u.hero).length,r.members);assert.ok(r.initial.filter(u=>u.hero).every(u=>u.rank===1));assert.ok(r.spawned<=r.expected);if(r.outcome==='clear'){assert.equal(r.spawned,r.expected);assert.equal(r.killed,r.expected);}if(r.hero&&r.members===4){const b=rows.find(b=>!b.hero&&b.difficulty===r.difficulty&&b.stage===r.stage&&b.quality===r.quality&&b.race===r.race&&b.mode===r.mode);assert.deepEqual(r.initial.filter(u=>!u.hero).map(u=>({id:u.id,rank:u.rank})),b.initial.map(u=>({id:u.id,rank:u.rank})));}}
 const current=JSON.parse(fs.readFileSync('reports/local/g03-economy-20261023/verification.json','utf8')).gameSource.current;assert.equal(crypto.createHash('sha256').update(fs.readFileSync(current.file)).digest('hex'),current.sha256);
 fs.writeFileSync(root+'/integrity.json',JSON.stringify({pass:true,uniqueRows:rows.length,completeCells:72,rowsPerCell:39,ordinaryIdentityPairsExact:true,ordinaryBaseBeforeHeroExact:JSON.parse(fs.readFileSync(root+'/pair-setup-proof.json','utf8')).baseBeforeHeroExact,nativeAcquisitionAttributesExact:JSON.parse(fs.readFileSync(root+'/pair-setup-proof.json','utf8')).afterNativeHeroExact,heroesRankOne:true,sourceUnchanged:out.sourceUnchanged,currentUnchanged:current},null,2));
}
